-- Linha Imprimax DecorMax na loja (31/10/2026).
-- Gerado de scripts/data/imprimax/_banco.json (scripts/generate-imprimax.mjs).
-- Os 157 SKUs IMX continuam ocultos (oculto_manual): vão ao ar num passo à parte.

begin;

-- backup antes de mexer
create table if not exists bkp_imprimax_produtos_20261031 as select * from produtos where erp_sku like 'IMX%';
create table if not exists bkp_imprimax_loja_config_20261031 as select * from loja_config where id = 1;

-- 1. Linha fora de cupom, cashback e comissão, e teto de parcelas por linha
alter table loja_config add column if not exists parcelas_max_por_linha jsonb not null default '{}'::jsonb;
update loja_config
   set linhas_excluidas = (select array(select distinct unnest(coalesce(linhas_excluidas, '{}') || array['imprimax']))),
       parcelas_max_por_linha = parcelas_max_por_linha || '{"imprimax": 3}'::jsonb
 where id = 1;

-- 2. A linha (ficha, textos, galeria de ambientes por família)
insert into linhas (linha_key, label, marca_key, ficha, chamada, descricao, texto_venda, aplicacoes, fonte_url, fonte_nota, publicado, ordem, pagina_url, galeria)
values (
  'imprimax', 'Imprimax DecorMax', 'imprimax', $json$[{"label":"Material","value":"PVC polimérico calandrado (frontal Gold)"},{"label":"Adesivo","value":"Acrílico aquoso permanente, sensível à pressão, atóxico"},{"label":"Liner","value":"Papel siliconado 120 g/m² (Fórmica Laca: poliéster 120 g/m²)"},{"label":"Proteção","value":"Antimofo, antibacteriano, não propaga fogo"},{"label":"Temperatura","value":"Até 70 °C a 30 cm da fonte de calor"},{"label":"Fabricação","value":"Indústria nacional — Imprimax"}]$json$::jsonb,
  'Vinil adesivo decorativo nacional: madeiras, mármores, fórmicas e tecidos com textura realista.',
  'Linha DecorMax Gold da Imprimax, indústria brasileira de vinil adesivo. Frontal em PVC polimérico calandrado, adesivo acrílico permanente e atóxico. Antimofo, antibacteriano e não propaga fogo. Mais de 120 padrões em madeiras, pedras, fórmicas, tecidos, couros e piso vinílico.',
  E'A DecorMax é a linha de vinil decorativo da Imprimax, fabricante nacional de adesivos. Os padrões Gold reproduzem madeira, pedra, fórmica, tecido e couro com textura na superfície, para renovar móveis, paredes e portas sem obra.

Para quem aplica: o adesivo acrílico é permanente e sensível à pressão, e a espessura do frontal varia por coleção (de 140 a 250 micras, na ficha de cada padrão). Fabricação no Brasil, sem prazo de importação.',
  array['Móveis planejados e reforma de mobiliário', 'Paredes e painéis internos', 'Portas', 'Ambientação comercial'],
  'https://www.imprimax.com.br/decormax',
  'Dados das páginas de família do fabricante (lidas em 31/10/2026). Espessura frontal e liner ficam no produto: variam por coleção. Ambientes da galeria são por família, não de um padrão.',
  true, 30, '/decor/imprimax', $json$[{"url":"/assets/images/decor/imprimax/familias/gold-madeiras-1.jpg","titulo":"Gold Madeiras","sub":"Madeira"},{"url":"/assets/images/decor/imprimax/familias/gold-madeiras-2.jpg","titulo":"Gold Madeiras","sub":"Madeira"},{"url":"/assets/images/decor/imprimax/familias/gold-pedras-1.jpg","titulo":"Gold Pedras","sub":"Pedra & Mármore"},{"url":"/assets/images/decor/imprimax/familias/gold-pedras-2.jpg","titulo":"Gold Pedras","sub":"Pedra & Mármore"},{"url":"/assets/images/decor/imprimax/familias/formica-laca-1.jpg","titulo":"Gold Fórmica Laca","sub":"Fórmica"},{"url":"/assets/images/decor/imprimax/familias/formica-laca-2.jpg","titulo":"Gold Fórmica Laca","sub":"Fórmica"},{"url":"/assets/images/decor/imprimax/familias/gold-telado-1.jpg","titulo":"Gold Telado","sub":"Tecido & Telado"},{"url":"/assets/images/decor/imprimax/familias/gold-telado-2.jpg","titulo":"Gold Telado","sub":"Tecido & Telado"},{"url":"/assets/images/decor/imprimax/familias/gold-couros-1.jpg","titulo":"Gold Couros","sub":"Couro & Texturas"},{"url":"/assets/images/decor/imprimax/familias/gold-couros-2.jpg","titulo":"Gold Couros","sub":"Couro & Texturas"},{"url":"/assets/images/decor/imprimax/familias/gold-metal-1.jpg","titulo":"Gold Metal","sub":"Metal"},{"url":"/assets/images/decor/imprimax/familias/gold-metal-2.jpg","titulo":"Gold Metal","sub":"Metal"},{"url":"/assets/images/decor/imprimax/familias/pisomax-decorativo-1.jpg","titulo":"PisoMax Decorativo","sub":"PisoMax"},{"url":"/assets/images/decor/imprimax/familias/pisomax-decorativo-2.jpg","titulo":"PisoMax Decorativo","sub":"PisoMax"}]$json$::jsonb
)
on conflict (linha_key) do update set
  label = excluded.label, marca_key = excluded.marca_key, ficha = excluded.ficha, chamada = excluded.chamada,
  descricao = excluded.descricao, texto_venda = excluded.texto_venda, aplicacoes = excluded.aplicacoes,
  fonte_url = excluded.fonte_url, fonte_nota = excluded.fonte_nota, pagina_url = excluded.pagina_url,
  galeria = excluded.galeria, atualizado_em = now();

-- 3. Todos os 157 IMX saem de "outro / diversos" para a linha (nome sem "Gold")
update produtos
   set brand_key = 'imprimax', linha_key = 'imprimax', linha_label = 'Imprimax DecorMax',
       marca_exibicao = 'Imprimax DecorMax', vertical = 'DECOR', kind = 'padrao',
       aplicacoes = array['arquitetonico'], nome = regexp_replace(nome, '^Gold\s+', '', 'i'),
       atualizado_em = now()
 where erp_sku like 'IMX%';

