    as x(sku text, slug text, nome text, subtitulo text, familia_padrao text, descricao text, ficha jsonb, badges text[], durabilidade_anos int, seo_titulo text, seo_descricao text, midias jsonb)
)
update produtos p
   set slug = d.slug, nome = d.nome, subtitulo = d.subtitulo, familia_padrao = d.familia_padrao,
       descricao = d.descricao, ficha = d.ficha, badges = d.badges, durabilidade_anos = d.durabilidade_anos,
       seo_titulo = d.seo_titulo, seo_descricao = d.seo_descricao, atualizado_em = now()
  from d
 where p.erp_sku = d.sku;

-- 5. Fotos (o gatilho espelha em produtos.imagem/galeria)
delete from produto_midia where produto_id in (select id from produtos where erp_sku like 'IMX%');
insert into produto_midia (produto_id, tipo, url, alt, ordem, capa, origem)
select p.id, 'imagem', m->>'url', m->>'alt', (m->>'ordem')::int, (m->>'capa')::boolean, 'estatico'
