ite — Imprimax DecorMax"}]},{"sku":"IMX14010019","midias":[{"url":"/assets/images/decor/imprimax/telado-linho-palha/texture.jpg","ordem":0,"capa":true,"alt":"Vinil adesivo Telado Linho Palha — Imprimax DecorMax"}]},{"sku":"IMX14010005","midias":[{"url":"/assets/images/decor/imprimax/telado-preto/texture.jpg","ordem":0,"capa":true,"alt":"Vinil adesivo Telado Preto — Imprimax DecorMax"}]}]$json$::jsonb) as x(sku text, midias jsonb)
  join produtos p on p.erp_sku = x.sku
  cross join lateral jsonb_array_elements(x.midias) m;

-- 6. Frete: rolo 1,22 × 25 m, os mesmos números do rolo Etherna
insert into shipping_profiles (nome, formato, peso_kg, comprimento_cm, largura_cm, altura_cm, observacao, ativo, valor_declarado, dias_producao, itens_por_volume, peso_adicional_kg)
select 'Rolo Imprimax DecorMax 1,22 × 25 m', formato, peso_kg, comprimento_cm, largura_cm, altura_cm,
       'Copiado do rolo Etherna (mesma medida). Conferir o peso real do rolo Imprimax.', true, valor_declarado, dias_producao, itens_por_volume, peso_adicional_kg
  from shipping_profiles
 where nome = 'Rolo Etherna Decor 1,22 × 25 m'
   and not exists (select 1 from shipping_profiles where nome = 'Rolo Imprimax DecorMax 1,22 × 25 m');
insert into shipping_profile_lines (profile_id, line_key, is_default)
select id, 'imprimax', true from shipping_profiles where nome = 'Rolo Imprimax DecorMax 1,22 × 25 m'
on conflict (profile_id, line_key) do nothing;

commit;

notify pgrst, 'reload schema';
